css:
.uic-pixel-card {
  font-family: "Courier New", monospace;
  font-size: 1em;
  background: #ff6b35;
  color: #fff;
  width: 20em;
  padding: 1em;
  image-rendering: pixelated;
  text-shadow: 1px 1px #000;
  box-shadow:
    0 0 0 0.15em #000,
    0 0 0 0.3em #fff,
    0 0 0 0.45em #000,
    0 0.5em 0 0 #d1451e,
    0 0.5em 0 0.15em #000;
  transition: transform 0.2s steps(1);
}

.uic-pixel-card:hover {
  transform: translateY(-0.2em);
  animation: uic-card-glitch 0.3s steps(2) infinite;
  background: #ff8c42;
}

.uic-card-header {
  font-size: 1.2em;
  margin-bottom: 0.5em;
  border-bottom: 2px solid #000;
  padding-bottom: 0.25em;
}

.uic-card-body p {
  margin: 0.5em 0;
  line-height: 1.4;
}

.status {
  color: #00ff99;
  font-weight: bold;
  text-shadow: 1px 1px #000;
}

/* Glitch animation */
@keyframes uic-card-glitch {
  0% {
    transform: translate(0, 0);
  }
  25% {
    transform: translate(-1px, 1px);
  }
  50% {
    transform: translate(1px, -1px);
  }
  75% {
    transform: translate(-1px, -1px);
  }
  100% {
    transform: translate(0, 0);
  }
}
